const streamCache = new Map();
const quickPicksCache = new Map();
let visitorCache = { expiresAt: 0, value: "" };

const MOOD_QUERIES = {
  all: ["Lagu Indonesia Populer Terbaru", "Global Top Hits 2025"],
  pop: ["Pop Indonesia Terbaru Hits", "Lagu Indonesia Viral 2025"],
  galau: ["Lagu Galau Indonesia Terbaru", "Lagu Sedih Indonesia Populer"],
  koplo: ["Lagu Jawa Populer Terbaru", "Musik Koplo Viral Terbaru"],
  chill: ["Indie Indonesia Chill", "Lofi Chill Acoustic"],
  global: ["Global Top Hits 2025", "Top Pop English Songs"],
  remix: ["DJ Remix Viral Terbaru", "Phonk Viral Hits"],
};

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

function parseDurationString(raw) {
  const parts = String(raw || "")
    .trim()
    .split(":")
    .map((p) => Number(p));
  if (parts.some((n) => !Number.isFinite(n))) return 0;
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return 0;
}

function extractRuns(column) {
  const runs = column?.musicResponsiveListItemFlexColumnRenderer?.text?.runs;
  if (!Array.isArray(runs)) return [];
  return runs.map((r) => r?.text).filter((t) => typeof t === "string");
}

function upgradeArtwork(url) {
  if (!url) return "";
  return url
    .replace("w60-h60", "w544-h544")
    .replace("w120-h120", "w544-h544")
    .replace("w226-h226", "w544-h544");
}

function parseSongRenderer(renderer) {
  const videoId =
    renderer?.playlistItemData?.videoId ||
    renderer?.overlay?.musicItemThumbnailOverlayRenderer?.content?.musicPlayButtonRenderer
      ?.playNavigationEndpoint?.watchEndpoint?.videoId;

  if (!videoId || typeof videoId !== "string") return null;

  const flexColumns = Array.isArray(renderer.flexColumns) ? renderer.flexColumns : [];
  const title = extractRuns(flexColumns[0]).join("").trim() || "Unknown Track";

  const subRuns = extractRuns(flexColumns[1])
    .map((s) => s.trim())
    .filter((s) => s && s !== "•" && s !== "·" && s !== ",");

  let artist = "Unknown Artist";
  let duration = 0;

  if (subRuns.length > 0) {
    const maybeDuration = parseDurationString(subRuns[subRuns.length - 1]);
    if (maybeDuration > 0) {
      duration = maybeDuration;
      const joined = subRuns.slice(0, -1).join(" ").trim();
      if (joined) artist = joined;
    } else {
      artist = subRuns[0];
    }
  }

  const thumbs = renderer?.thumbnail?.musicThumbnailRenderer?.thumbnail?.thumbnails;
  const rawThumb = Array.isArray(thumbs) && thumbs.length > 0 ? thumbs[thumbs.length - 1]?.url : "";

  return {
    id: videoId,
    title,
    artist,
    thumbnail: upgradeArtwork(rawThumb),
    duration,
  };
}

function collectSongs(node, results, seen) {
  if (!node || typeof node !== "object") return;
  if (Array.isArray(node)) {
    for (const item of node) collectSongs(item, results, seen);
    return;
  }
  if (node.musicResponsiveListItemRenderer) {
    const song = parseSongRenderer(node.musicResponsiveListItemRenderer);
    if (song && !seen.has(song.id)) {
      seen.add(song.id);
      results.push(song);
    }
  }
  for (const val of Object.values(node)) {
    if (val && typeof val === "object") {
      collectSongs(val, results, seen);
    }
  }
}

async function searchSongs(query) {
  const trimmed = String(query || "").trim();
  if (!trimmed) return [];

  const response = await fetch("https://music.youtube.com/youtubei/v1/search?prettyPrint=false", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Origin: "https://music.youtube.com",
      Referer: "https://music.youtube.com/",
      "User-Agent":
        "Mozilla/5.0 (iPhone; CPU iPhone OS 18_3 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.3 Mobile/15E148 Safari/604.1",
    },
    body: JSON.stringify({
      context: {
        client: {
          clientName: "WEB_REMIX",
          clientVersion: "1.20250310.01.00",
          hl: "id",
          gl: "ID",
        },
      },
      query: trimmed,
      params: "EgWKAQIIAWoMEAMQBBAJEAoQBRAV",
    }),
  });

  if (!response.ok) {
    throw new Error("YouTube Music search HTTP " + response.status);
  }

  const json = await response.json();
  const results = [];
  const seen = new Set();
  collectSongs(json, results, seen);
  return results;
}

async function getQuickPicks(mood = "all") {
  const key = MOOD_QUERIES[mood] ? mood : "all";
  const cached = quickPicksCache.get(key);
  if (cached && Date.now() < cached.expiresAt && cached.songs.length > 0) {
    return cached.songs;
  }

  const queries = MOOD_QUERIES[key];
  const settled = await Promise.allSettled(queries.map((q) => searchSongs(q)));
  const combined = [];
  const seen = new Set();

  for (const res of settled) {
    if (res.status === "fulfilled") {
      for (const song of res.value.slice(0, 10)) {
        if (!seen.has(song.id)) {
          seen.add(song.id);
          combined.push(song);
        }
      }
    }
  }

  if (combined.length > 0) {
    quickPicksCache.set(key, { expiresAt: Date.now() + 30 * 60_000, songs: combined });
  }
  return combined;
}

async function getVisitorData() {
  if (visitorCache.value && Date.now() < visitorCache.expiresAt) {
    return visitorCache.value;
  }
  try {
    const res = await fetch("https://music.youtube.com/youtubei/v1/visitor_id?prettyPrint=false", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        context: { client: { clientName: "WEB_REMIX", clientVersion: "1.20250310.01.00" } },
      }),
    });
    if (res.ok) {
      const data = await res.json();
      const v = data?.responseContext?.visitorData;
      if (typeof v === "string" && v.length > 0) {
        visitorCache = { expiresAt: Date.now() + 30 * 60_000, value: v };
        return v;
      }
    }
  } catch {}
  return "";
}

const INNERTUBE_CLIENTS = [
  {
    clientName: "VISIONOS",
    clientVersion: "1.02",
    headerId: "101",
    userAgent:
      "Mozilla/5.0 (Macintosh; Intel Mac OS X 15_7_3) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/26.0 Safari/605.1.15",
    extra: {
      deviceMake: "Apple",
      deviceModel: "RealityDevice17,1",
      osName: "visionOS",
      osVersion: "26.5.23O471",
    },
  },
  {
    clientName: "IOS",
    clientVersion: "20.10.4",
    headerId: "5",
    userAgent: "com.google.ios.youtube/20.10.4 (iPhone16,2; U; CPU iOS 18_3_2 like Mac OS X;)",
    extra: {
      deviceMake: "Apple",
      deviceModel: "iPhone16,2",
      osName: "iOS",
      osVersion: "18.3.2.22D82",
    },
  },
];

async function fetchPlayerForClient(videoId, client, visitorData) {
  const headers = {
    "Content-Type": "application/json",
    "User-Agent": client.userAgent,
    "X-YouTube-Client-Name": client.headerId,
    "X-YouTube-Client-Version": client.clientVersion,
    Origin: "https://www.youtube.com",
  };
  if (visitorData) headers["X-Goog-Visitor-Id"] = visitorData;

  const clientCtx = {
    clientName: client.clientName,
    clientVersion: client.clientVersion,
    hl: "en",
    gl: "US",
    ...client.extra,
  };
  if (visitorData) clientCtx.visitorData = visitorData;

  const response = await fetch("https://www.youtube.com/youtubei/v1/player?prettyPrint=false", {
    method: "POST",
    headers,
    body: JSON.stringify({
      context: { client: clientCtx },
      videoId,
      contentCheckOk: true,
      racyCheckOk: true,
    }),
  });

  if (!response.ok) {
    throw new Error(client.clientName + " HTTP " + response.status);
  }

  const json = await response.json();
  const status = json?.playabilityStatus?.status;
  if (status && status !== "OK") {
    throw new Error(json?.playabilityStatus?.reason || status);
  }

  const adaptive = Array.isArray(json?.streamingData?.adaptiveFormats)
    ? json.streamingData.adaptiveFormats
    : [];
  const muxed = Array.isArray(json?.streamingData?.formats) ? json.streamingData.formats : [];

  for (const itag of [140, 139, 141]) {
    const match = adaptive.find((f) => Number(f?.itag) === itag && typeof f?.url === "string");
    if (match) {
      return {
        url: match.url,
        mimeType: match.mimeType || "audio/mp4",
        userAgent: client.userAgent,
        contentLength: Number(match.contentLength || 0),
      };
    }
  }

  const mp4Audio = adaptive
    .filter((f) => String(f?.mimeType || "").toLowerCase().includes("audio/mp4") && typeof f?.url === "string")
    .sort((a, b) => Number(b?.bitrate || 0) - Number(a?.bitrate || 0));

  if (mp4Audio.length > 0) {
    return {
      url: mp4Audio[0].url,
      mimeType: mp4Audio[0].mimeType || "audio/mp4",
      userAgent: client.userAgent,
      contentLength: Number(mp4Audio[0].contentLength || 0),
    };
  }

  const mp4Muxed = muxed.find(
    (f) => String(f?.mimeType || "").toLowerCase().includes("mp4") && typeof f?.url === "string"
  );
  if (mp4Muxed) {
    return {
      url: mp4Muxed.url,
      mimeType: "audio/mp4",
      userAgent: client.userAgent,
      contentLength: Number(mp4Muxed.contentLength || 0),
    };
  }

  throw new Error(client.clientName + ": no playable MP4/AAC url");
}

async function resolveStream(videoId, forceRefresh = false) {
  if (!forceRefresh) {
    const cached = streamCache.get(videoId);
    if (cached && Date.now() < cached.expiresAt) {
      return cached;
    }
  }

  const visitorData = await getVisitorData();
  let lastError = null;
  for (const client of INNERTUBE_CLIENTS) {
    try {
      const resolved = await fetchPlayerForClient(videoId, client, visitorData);
      const entry = { ...resolved, expiresAt: Date.now() + 20 * 60_000 };
      streamCache.set(videoId, entry);
      return entry;
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError || new Error("Gagal mendapatkan stream audio");
}

const STREAM_CHUNK_SIZE = 2 * 1024 * 1024;

function parseByteRange(rangeHeader) {
  const m = String(rangeHeader || "").match(/bytes=(\d+)-(\d*)/i);
  if (!m) return { start: 0, reqEnd: null };
  return {
    start: Number(m[1]),
    reqEnd: m[2] ? Number(m[2]) : null,
  };
}

async function handleStreamProxy(request, videoId) {
  if (!/^[a-zA-Z0-9_-]{6,20}$/.test(videoId)) {
    return jsonResponse({ error: "Invalid videoId" }, 400);
  }

  let resolved;
  try {
    resolved = await resolveStream(videoId, false);
  } catch (err) {
    return jsonResponse({ error: err?.message || "Stream resolution failed" }, 502);
  }

  if (request.method === "HEAD") {
    let totalLen = resolved.contentLength || 0;
    if (totalLen <= 0) {
      const probe = await fetch(resolved.url, {
        headers: { "User-Agent": resolved.userAgent, Range: "bytes=0-0" },
      });
      await probe.body?.cancel?.();
      const cr = probe.headers.get("content-range") || "";
      const m = cr.match(/\/(\d+)$/);
      if (m) totalLen = Number(m[1]);
    }
    const headHeaders = new Headers({
      "Content-Type": "audio/mp4",
      "Accept-Ranges": "bytes",
      "Cache-Control": "no-store",
      "Access-Control-Allow-Origin": "*",
    });
    if (totalLen > 0) headHeaders.set("Content-Length", String(totalLen));
    return new Response(null, { status: 200, headers: headHeaders });
  }

  const { start, reqEnd } = parseByteRange(request.headers.get("range"));
  if (resolved.contentLength > 0 && start >= resolved.contentLength) {
    return new Response(null, {
      status: 416,
      headers: {
        "Content-Range": "bytes */" + resolved.contentLength,
        "Access-Control-Allow-Origin": "*",
      },
    });
  }

  const fetchBounded = (target) => {
    let end = reqEnd !== null ? Math.min(reqEnd, start + STREAM_CHUNK_SIZE - 1) : start + STREAM_CHUNK_SIZE - 1;
    if (target.contentLength > 0) {
      end = Math.min(end, target.contentLength - 1);
    }
    const headers = new Headers();
    headers.set("User-Agent", target.userAgent);
    headers.set("Range", "bytes=" + start + "-" + end);
    return fetch(target.url, { method: "GET", headers });
  };

  let upstream = await fetchBounded(resolved);
  if (upstream.status === 403 || upstream.status === 404 || upstream.status === 410) {
    await upstream.body?.cancel?.();
    resolved = await resolveStream(videoId, true);
    upstream = await fetchBounded(resolved);
  }

  if (!upstream.ok && upstream.status !== 206) {
    return jsonResponse({ error: "Upstream audio returned HTTP " + upstream.status }, 502);
  }

  const outHeaders = new Headers();
  outHeaders.set("Content-Type", (upstream.headers.get("content-type") || "audio/mp4").split(";")[0]);
  outHeaders.set("Accept-Ranges", upstream.headers.get("accept-ranges") || "bytes");
  outHeaders.set("Cache-Control", "no-store");
  outHeaders.set("Access-Control-Allow-Origin", "*");

  const contentLength = upstream.headers.get("content-length");
  if (contentLength) outHeaders.set("Content-Length", contentLength);
  const contentRange = upstream.headers.get("content-range");
  if (contentRange) outHeaders.set("Content-Range", contentRange);

  return new Response(upstream.body, {
    status: upstream.status,
    headers: outHeaders,
  });
}

function cleanMetadata(raw) {
  return String(raw || "")
    .replace(/\(feat\.[^)]*\)/gi, "")
    .replace(/\(ft\.[^)]*\)/gi, "")
    .replace(/\[[^\]]*\]/g, "")
    .replace(/\(Official[^)]*\)/gi, "")
    .replace(/\(Lyric[^)]*\)/gi, "")
    .replace(/\(Audio[^)]*\)/gi, "")
    .replace(/\(Music Video[^)]*\)/gi, "")
    .trim();
}

function normalizeFold(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function foldTitle(s) {
  const cut = String(s || "").split(" (")[0].split(" [")[0].split(" - ")[0];
  return normalizeFold(cut);
}

function decodeXmlEntities(s) {
  return String(s || "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&#32;/g, " ")
    .replace(/&#10;/g, " ")
    .replace(/&#13;/g, "");
}

function parseTimeStr(raw) {
  const t = String(raw || "").trim();
  if (!t) return -1;
  if (/^\d+(?:\.\d+)?ms$/i.test(t)) return Math.round(parseFloat(t));
  if (/^\d+(?:\.\d+)?h$/i.test(t)) return Math.round(parseFloat(t) * 3_600_000);
  if (/^\d+(?:\.\d+)?m$/i.test(t)) return Math.round(parseFloat(t) * 60_000);
  if (/^\d+(?:\.\d+)?s$/i.test(t)) return Math.round(parseFloat(t) * 1000);
  const parts = t.split(":").map((p) => Number(p));
  if (parts.some((n) => !Number.isFinite(n))) return -1;
  if (parts.length === 1) return Math.round(parts[0] * 1000);
  if (parts.length === 2) return Math.round(parts[0] * 60_000 + parts[1] * 1000);
  if (parts.length === 3) return Math.round(parts[0] * 3_600_000 + parts[1] * 60_000 + parts[2] * 1000);
  return -1;
}

function getXmlAttr(attrs, name) {
  const re = new RegExp("(?:^|\\s)" + name + "\\s*=\\s*[\"']([^\"']*)[\"']", "i");
  const m = String(attrs || "").match(re);
  return m ? m[1] : "";
}

function mergeWordSegments(segments, lineEndMs) {
  const words = [];
  let current = null;
  for (const seg of segments) {
    const raw = seg.text;
    if (!raw) continue;
    if (/^\s/.test(raw) && current) {
      words.push(current);
      current = null;
    }
    const trimmed = raw.trim();
    if (trimmed) {
      if (!current) {
        current = { word: trimmed, startMs: seg.startMs, endMs: seg.endMs };
      } else {
        current.word += trimmed;
        if (seg.endMs > current.endMs) current.endMs = seg.endMs;
      }
    }
    if (/\s$/.test(raw) && current) {
      words.push(current);
      current = null;
    }
  }
  if (current) words.push(current);
  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    if (w.endMs <= w.startMs) {
      const next = words[i + 1];
      w.endMs = next ? Math.max(w.startMs + 80, next.startMs) : Math.max(w.startMs + 320, lineEndMs || w.startMs + 320);
    }
  }
  return words;
}

function parseTtml(xml) {
  const cleanXml = String(xml || "").replace(/<span\b[^>]*role\s*=\s*["']x-bg["'][^>]*>[\s\S]*?<\/span>/gi, "");
  const pRegex = /<p\b([^>]*)>([\s\S]*?)<\/p>/gi;
  const spanRegex = /<span\b([^>]*)>([\s\S]*?)<\/span>/gi;
  const lines = [];
  let hasWordSync = false;

  for (const pm of cleanXml.matchAll(pRegex)) {
    const pAttrs = pm[1] || "";
    const pInner = pm[2] || "";
    const beginMs = parseTimeStr(getXmlAttr(pAttrs, "begin"));
    const endMs = parseTimeStr(getXmlAttr(pAttrs, "end"));
    if (beginMs < 0) continue;

    const segments = [];
    let cursor = 0;
    let spanCount = 0;
    for (const sm of pInner.matchAll(spanRegex)) {
      const idx = sm.index || 0;
      if (idx > cursor) {
        const between = decodeXmlEntities(pInner.slice(cursor, idx).replace(/<[^>]+>/g, ""));
        if (/\s/.test(between) && segments.length > 0) {
          segments.push({ text: " ", startMs: segments[segments.length - 1].endMs, endMs: segments[segments.length - 1].endMs });
        }
      }
      const sAttrs = sm[1] || "";
      const sText = decodeXmlEntities(sm[2].replace(/<[^>]+>/g, ""));
      const sb = parseTimeStr(getXmlAttr(sAttrs, "begin"));
      const se = parseTimeStr(getXmlAttr(sAttrs, "end"));
      if (sb >= 0 && sText) {
        spanCount++;
        segments.push({
          text: sText,
          startMs: sb,
          endMs: se > sb ? se : sb + 260,
        });
      }
      cursor = idx + sm[0].length;
    }

    const words = spanCount > 0 ? mergeWordSegments(segments, endMs) : [];
    const plain = words.length > 0
      ? words.map((w) => w.word).join(" ")
      : decodeXmlEntities(pInner.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
    if (!plain) continue;

    if (words.length > 0) hasWordSync = true;
    lines.push({
      timeMs: beginMs,
      endMs: endMs > beginMs ? endMs : undefined,
      text: plain,
      ...(words.length > 0 ? { words } : {}),
    });
  }

  lines.sort((a, b) => a.timeMs - b.timeMs);
  return {
    lines: lines.map((line, idx) => ({ id: idx, ...line })),
    syncType: hasWordSync ? "word" : "line",
  };
}

function parseLrc(lrc) {
  const lines = [];
  const lineTsRegex = /\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]/g;
  const wordTsRegex = /<(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?>/g;
  const metaTagRegex = /^\[(ti|ar|al|au|lr|length|by|offset|re|tool|ve|#):([^\]]*)\]$/i;
  let globalOffsetMs = 0;
  let hasWordSync = false;

  for (const rawLine of String(lrc || "").split(/\r?\n/)) {
    const trimmed = rawLine.trim();
    if (!trimmed) continue;
    const metaMatch = trimmed.match(metaTagRegex);
    if (metaMatch) {
      if (metaMatch[1].toLowerCase() === "offset") {
        const val = Number(metaMatch[2].trim());
        if (Number.isFinite(val)) globalOffsetMs = val;
      }
      continue;
    }

    const matches = [...trimmed.matchAll(lineTsRegex)];
    if (matches.length === 0) continue;
    const last = matches[matches.length - 1];
    let body = trimmed.slice((last.index || 0) + last[0].length).trim();
    body = body.replace(/\[bg:[^\]]*\]/gi, "").trim();
    if (!body) continue;

    const wordMatches = [...body.matchAll(wordTsRegex)];
    let parsedWords = [];
    let cleanText = body;

    if (wordMatches.length > 0) {
      hasWordSync = true;
      const segs = [];
      for (let wi = 0; wi < wordMatches.length; wi++) {
        const wm = wordMatches[wi];
        const nextWm = wordMatches[wi + 1];
        const wStart = parseTimeStr(wm[0].slice(1, -1)) - globalOffsetMs;
        const wEnd = nextWm ? parseTimeStr(nextWm[0].slice(1, -1)) - globalOffsetMs : wStart;
        const textStart = (wm.index || 0) + wm[0].length;
        const textEnd = nextWm ? nextWm.index || body.length : body.length;
        const segText = body.slice(textStart, textEnd);
        if (wStart >= 0 && segText) {
          segs.push({ text: segText, startMs: Math.max(0, wStart), endMs: Math.max(0, wEnd) });
        }
      }
      parsedWords = mergeWordSegments(segs, 0);
      cleanText = parsedWords.map((w) => w.word).join(" ").trim();
      if (!cleanText) continue;
    }

    for (const m of matches) {
      const mins = Number(m[1] || 0);
      const secs = Number(m[2] || 0);
      const frac = String(m[3] || "");
      let ms = 0;
      if (frac.length === 1) ms = Number(frac) * 100;
      else if (frac.length === 2) ms = Number(frac) * 10;
      else if (frac.length >= 3) ms = Number(frac.slice(0, 3));
      const timeMs = Math.max(0, mins * 60_000 + secs * 1000 + ms - globalOffsetMs);
      lines.push({
        timeMs,
        text: cleanText,
        ...(parsedWords.length > 0 ? { words: parsedWords } : {}),
      });
    }
  }

  lines.sort((a, b) => a.timeMs - b.timeMs);
  for (let i = 0; i < lines.length; i++) {
    const next = lines[i + 1];
    if (lines[i].words && lines[i].words.length > 0 && next) {
      const lastW = lines[i].words[lines[i].words.length - 1];
      if (lastW.endMs <= lastW.startMs || lastW.endMs > next.timeMs + 400) {
        lastW.endMs = Math.max(lastW.startMs + 240, Math.min(next.timeMs, lastW.startMs + 850));
      }
    }
  }
  return {
    lines: lines.map((line, idx) => ({ id: idx, ...line })),
    syncType: hasWordSync ? "word" : "line",
  };
}

function parsePlainLyrics(text) {
  const lines = String(text || "")
    .split(/\r?\n/)
    .map((s) => s.trim())
    .filter(Boolean)
    .map((lineText, idx) => ({ id: idx, timeMs: -1, text: lineText }));
  return { lines, syncType: "plain" };
}

function parseLrcRecord(record) {
  if (record?.syncedLyrics && record.syncedLyrics.trim()) {
    const parsed = parseLrc(record.syncedLyrics);
    if (parsed.lines.length > 0) return parsed;
  }
  if (record?.plainLyrics && record.plainLyrics.trim()) {
    const plain = parsePlainLyrics(record.plainLyrics);
    if (plain.lines.length > 0) return plain;
  }
  return { lines: [], syncType: "none" };
}

async function fetchUnisonLyrics(videoId, cTitle, cArtist, duration) {
  const url = new URL("https://unison.betterlyrics.org/lyrics");
  if (videoId) url.searchParams.set("v", videoId);
  if (cTitle) url.searchParams.set("song", cTitle);
  if (cArtist) url.searchParams.set("artist", cArtist);
  url.searchParams.set("duration", String(duration > 0 ? Math.round(duration) : 0));

  const res = await fetch(url.toString(), {
    headers: { "User-Agent": "WhisMuno-PWA/" + APP_VERSION },
    signal: AbortSignal.timeout(4500),
  });
  if (!res.ok) return null;
  const json = await res.json();
  const data = json?.data;
  if (!data?.lyrics || typeof data.lyrics !== "string") return null;

  if (data.format === "ttml") {
    const parsed = parseTtml(data.lyrics);
    if (parsed.lines.length > 0) return { ...parsed, provider: "unison" };
  } else if (data.format === "lrc") {
    const parsed = parseLrc(data.lyrics);
    if (parsed.lines.length > 0) return { ...parsed, provider: "unison" };
  } else if (data.format === "plain") {
    const parsed = parsePlainLyrics(data.lyrics);
    if (parsed.lines.length > 0) return { ...parsed, provider: "unison" };
  }
  return null;
}

async function fetchLrcRedLyrics(cTitle, cArtist, duration) {
  const headers = { "User-Agent": "WhisMuno-PWA/" + APP_VERSION };
  const q = cArtist ? cTitle + " " + cArtist : cTitle;
  const searchUrl = new URL("https://lrc.red/search.json");
  searchUrl.searchParams.set("q", q);

  const sr = await fetch(searchUrl.toString(), { headers, signal: AbortSignal.timeout(4000) });
  if (!sr.ok) return null;
  const searchJson = await sr.json();
  const hits = Array.isArray(searchJson?.hits) ? searchJson.hits : [];

  const targetTitle = foldTitle(cTitle);
  const targetArtist = normalizeFold(cArtist);
  const rawLower = cTitle.toLowerCase();
  const variantRe = /\b(live|remix|karaoke|instrumental|cappella|sped up|slowed|acoustic|cover)\b/i;
  const wantsVariant = variantRe.test(rawLower);
  let bestHit = null;
  let bestScore = -1e9;

  for (const hit of hits) {
    const rawHitTitle = String(hit?.title || "");
    const ht = foldTitle(rawHitTitle);
    const ha = normalizeFold(hit?.artist || "");
    const titleOk = targetTitle && (ht === targetTitle || ht.includes(targetTitle) || targetTitle.includes(ht));
    const artistOk = !targetArtist || ha === targetArtist || ha.includes(targetArtist) || targetArtist.includes(ha);
    if (!titleOk || !artistOk) continue;

    const hitDur = Number(hit?.duration || 0);
    const diff = duration > 10 && hitDur > 0 ? Math.abs(duration - hitDur) : 0;
    if (diff > 20) continue;

    const base = ht === targetTitle ? 100 : 60;
    const variantPenalty = !wantsVariant && variantRe.test(rawHitTitle) ? 60 : 0;
    const score = base + (20 - diff) - variantPenalty;
    if (score > bestScore && /^[a-zA-Z0-9]+$/.test(String(hit?.isrc || ""))) {
      bestScore = score;
      bestHit = hit;
    }
  }

  if (!bestHit) return null;
  const ttmlRes = await fetch("https://lrc.red/s/" + bestHit.isrc + ".ttml", {
    headers,
    signal: AbortSignal.timeout(4000),
  });
  if (!ttmlRes.ok) return null;
  const ttmlText = await ttmlRes.text();
  const parsed = parseTtml(ttmlText);
  if (parsed.lines.length === 0) return null;
  const explicitWord = /lrc:timing\s*=\s*["'](?:Word|Syllable)["']/i.test(ttmlText);
  const explicitLine = /lrc:timing\s*=\s*["']Line["']/i.test(ttmlText);
  return {
    lines: parsed.lines,
    syncType: explicitLine ? "line" : explicitWord ? "word" : parsed.syncType,
    provider: "lrc.red",
  };
}

async function fetchLrclibLyrics(cTitle, cArtist, duration) {
  const headers = { "User-Agent": "WhisMuno-PWA/" + APP_VERSION };
  const exactUrl = new URL("https://lrclib.net/api/get");
  exactUrl.searchParams.set("track_name", cTitle);
  if (cArtist) exactUrl.searchParams.set("artist_name", cArtist);
  if (duration > 10) exactUrl.searchParams.set("duration", String(Math.round(duration)));

  try {
    const r1 = await fetch(exactUrl.toString(), { headers, signal: AbortSignal.timeout(4000) });
    if (r1.ok) {
      const parsed = parseLrcRecord(await r1.json());
      if (parsed.lines.length > 0 && parsed.syncType !== "plain") {
        return { ...parsed, provider: "lrclib" };
      }
    }
  } catch {}

  const searchUrl = new URL("https://lrclib.net/api/search");
  searchUrl.searchParams.set("q", (cTitle + " " + cArtist).trim());
  const r2 = await fetch(searchUrl.toString(), { headers, signal: AbortSignal.timeout(4500) });
  if (!r2.ok) return null;
  const list = await r2.json();
  if (!Array.isArray(list) || list.length === 0) return null;

  const targetTitle = foldTitle(cTitle);
  const targetArtist = normalizeFold(cArtist);
  let bestSynced = null;
  let bestScore = -1e9;
  let fallbackPlain = null;

  for (const item of list) {
    const parsed = parseLrcRecord(item);
    if (parsed.lines.length === 0) continue;
    if (parsed.syncType === "plain") {
      if (!fallbackPlain) fallbackPlain = { ...parsed, provider: "lrclib" };
      continue;
    }

    const it = foldTitle(item?.trackName || item?.name || "");
    const ia = normalizeFold(item?.artistName || "");
    const itemDur = Number(item?.duration || 0);
    const durDiff = duration > 10 && itemDur > 0 ? Math.abs(itemDur - duration) : 10;
    if (duration > 10 && durDiff > 25) continue;

    let score = 50 - durDiff * 2.5;
    if (it === targetTitle) score += 60;
    else if (targetTitle && (it.includes(targetTitle) || targetTitle.includes(it))) score += 30;
    if (targetArtist && (ia === targetArtist || ia.includes(targetArtist) || targetArtist.includes(ia))) score += 25;
    if (parsed.syncType === "word") score += 25;

    if (score > bestScore) {
      bestScore = score;
      bestSynced = { ...parsed, provider: "lrclib" };
    }
  }

  return bestSynced || fallbackPlain;
}

function rankLyricsCandidate(res) {
  if (!res || !Array.isArray(res.lines) || res.lines.length === 0) return -1;
  if (res.syncType === "word") {
    if (res.provider === "unison") return 6;
    if (res.provider === "lrc.red") return 5;
    return 4;
  }
  if (res.syncType === "line") {
    if (res.provider === "unison") return 3;
    if (res.provider === "lrc.red") return 2;
    return 1;
  }
  return 0;
}

async function fetchLyrics(videoId, title, artist, duration) {
  const cTitle = cleanMetadata(title);
  const cArtist = cleanMetadata(artist);
  if (!cTitle) return { lines: [], syncType: "none", provider: "none" };

  const settled = await Promise.allSettled([
    fetchUnisonLyrics(videoId, cTitle, cArtist, duration),
    fetchLrcRedLyrics(cTitle, cArtist, duration),
    fetchLrclibLyrics(cTitle, cArtist, duration),
  ]);

  let best = null;
  let bestRank = -1;
  for (const item of settled) {
    if (item.status !== "fulfilled" || !item.value) continue;
    const rank = rankLyricsCandidate(item.value);
    if (rank > bestRank) {
      bestRank = rank;
      best = item.value;
    }
  }

  return best || { lines: [], syncType: "none", provider: "none" };
}

export default {
  async fetch(request) {
    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, HEAD, OPTIONS",
          "Access-Control-Allow-Headers": "Range, Content-Type",
        },
      });
    }

    const url = new URL(request.url);
    const pathname = url.pathname;

    try {
      if (pathname === "/health") {
        return jsonResponse({ ok: true, version: APP_VERSION, runtime: "cloudflare-workers" });
      }

      if (pathname === "/api/search") {
        const q = url.searchParams.get("q") || "";
        const songs = await searchSongs(q);
        return jsonResponse({ songs });
      }

      if (pathname === "/api/quick-picks") {
        const mood = url.searchParams.get("mood") || "all";
        const songs = await getQuickPicks(mood);
        return jsonResponse({ songs });
      }

      if (pathname === "/api/lyrics") {
        const videoId = url.searchParams.get("videoId") || "";
        const title = url.searchParams.get("title") || "";
        const artist = url.searchParams.get("artist") || "";
        const duration = Number(url.searchParams.get("duration") || 0);
        const result = await fetchLyrics(videoId, title, artist, duration);
        return jsonResponse(result);
      }

      if (pathname === "/api/stream") {
        const videoId = url.searchParams.get("videoId") || "";
        return await handleStreamProxy(request, videoId);
      }

      if (pathname === "/icon.png") {
        const iconRes = await fetch(ICON_SOURCE_URL, {
          headers: { "User-Agent": "WhisMuno-PWA/" + APP_VERSION },
          cf: { cacheTtl: 86400, cacheEverything: true },
        });
        if (!iconRes.ok) {
          return new Response("Icon unavailable", { status: 404 });
        }
        return new Response(iconRes.body, {
          status: 200,
          headers: {
            "Content-Type": "image/png",
            "Cache-Control": "public, max-age=86400",
          },
        });
      }

      const key = pathname === "/" ? "/index.html" : pathname;
      const asset = ASSETS[key] || ASSETS["/index.html"];
      return new Response(asset.body, {
        status: 200,
        headers: {
          "Content-Type": asset.type,
          "Cache-Control":
            key === "/manifest.webmanifest" ? "public, max-age=3600" : "no-cache",
        },
      });
    } catch (err) {
      return jsonResponse({ error: err?.message || "Internal worker error" }, 500);
    }
  },
};
